//! Real renders of scenes that hold a video and sound, compiled by `facile-scene`. The media is
//! generated by ffmpeg. Skipped, loudly, when Chrome, ffmpeg or ffprobe is missing.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::process::Command;

use clap_render::{Job, Tools, render};
use serde_json::Value;

const SKIP: &str = "\n================ SKIPPED: clap-render needs chrome-headless-shell, ffmpeg and ffprobe \
    (CLAP_CHROME, CLAP_FFMPEG, CLAP_FFPROBE or PATH) ================\n";

const MOVING: &str = r##"---
title: Media
size: 640x360
layout: raw
duration: 2
---
<style>
  .scene { background: #101014; }
  #v { position: absolute; left: 40px; top: 40px; width: 320px; height: 180px; object-fit: cover; }
  #t { position: absolute; left: 40px; bottom: 30px; margin: 0; color: #f4f4f5; }
</style>
<video id="v" src="clip.mp4" data-start="0" data-duration="2" data-track-index="0"></video>
<h1 id="t" data-start="0" data-duration="2" data-track-index="1">Clap</h1>
<audio src="tone.wav" data-start="0.5" data-duration="1" data-volume="0.5"></audio>
<script>
  scene.timeline((tl) => {
    tl.fromTo("#v", { x: 0, rotate: 0 }, { x: 200, rotate: 10, duration: 2, ease: "none" }, 0);
    tl.from("#t", { opacity: 0, y: 40, duration: 0.8 }, 0);
  });
</script>
"##;

const RAMP: &str = r##"---
size: 64x36
layout: raw
duration: 1
---
<style>#v { position: absolute; inset: 0; width: 100%; height: 100%; }</style>
<video id="v" src="ramp.mp4" data-start="0.2" data-duration="0.5" data-in="0.2"></video>
"##;

fn tools() -> Option<(Tools, PathBuf)> {
    let found = Tools::locate().ok().zip(clap_render::tools::ffprobe());
    if found.is_none() {
        eprintln!("{SKIP}");
    }
    found
}

fn ffmpeg(tools: &Tools, args: &[&str], output: &Path) {
    let done = Command::new(&tools.ffmpeg)
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .arg(output)
        .output()
        .unwrap();
    assert!(done.status.success(), "{}", String::from_utf8_lossy(&done.stderr));
}

fn bundle(source: &str) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let project = scene::parse(source).unwrap();
    std::fs::write(dir.path().join("index.html"), scene::compile(&project, &scene::Options::new())).unwrap();
    dir
}

fn probe(ffprobe: &Path, file: &Path) -> Value {
    let entries = "stream=codec_type,codec_name,nb_read_frames:format=duration";
    let output = Command::new(ffprobe)
        .args(["-v", "error", "-count_frames", "-show_entries", entries, "-of", "json"])
        .arg(file)
        .output()
        .unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    serde_json::from_slice(&output.stdout).unwrap()
}

fn moving(tools: &Tools) -> tempfile::TempDir {
    let dir = bundle(MOVING);
    ffmpeg(
        tools,
        &["-f", "lavfi", "-i", "testsrc2=size=320x180:rate=30:duration=2", "-pix_fmt", "yuv420p"],
        &dir.path().join("clip.mp4"),
    );
    ffmpeg(tools, &["-f", "lavfi", "-i", "sine=frequency=440:duration=2"], &dir.path().join("tone.wav"));
    dir
}

#[test]
fn a_video_under_a_transform_with_a_tween_and_sound_renders_the_same_twice() {
    let Some((tools, ffprobe)) = tools() else { return };
    let dir = moving(&tools);
    let out = tempfile::tempdir().unwrap();
    let job = |name: &str| Job { width: 640, height: 360, ..Job::new(dir.path(), out.path().join(name)) };
    let a = render(&job("a.mp4"), &tools).unwrap();
    let b = render(&job("b.mp4"), &tools).unwrap();
    eprintln!(
        "media render: {} frames in {:?} then {:?}, {} video, {} audio track",
        a.frames, a.elapsed, b.elapsed, a.videos, a.audio_tracks
    );
    assert_eq!((a.frames, a.duration, a.videos, a.audio_tracks), (60, 2.0, 1, 1), "{:?}", a.blocked);
    assert_eq!(a.frame_hashes, b.frame_hashes, "two runs must capture the same pixels");
    assert_eq!(a.frame_hashes.iter().collect::<HashSet<_>>().len(), 60, "every frame must show a new still");
    let probed = probe(&ffprobe, &out.path().join("a.mp4"));
    let streams = probed["streams"].as_array().unwrap();
    let stream = |kind: &str| streams.iter().find(|stream| stream["codec_type"] == kind).unwrap_or(&Value::Null);
    assert_eq!(
        (&stream("video")["codec_name"], &stream("video")["nb_read_frames"]),
        (&Value::from("h264"), &Value::from("60"))
    );
    assert_eq!(stream("audio")["codec_name"], "aac", "{probed}");
    let seconds = probed["format"]["duration"].as_str().and_then(|text| text.parse::<f64>().ok());
    assert!(seconds.is_some_and(|seconds| (seconds - 2.0).abs() < 0.05), "the file lasts {seconds:?} s");
    let left: Vec<_> = std::fs::read_dir(dir.path()).unwrap().map(|entry| entry.unwrap().file_name()).collect();
    assert_eq!(left.len(), 3, "extracted frames were left in the bundle: {left:?}");
}

#[test]
fn each_output_frame_shows_the_source_frame_of_its_time() {
    let Some((tools, _)) = tools() else { return };
    let dir = bundle(RAMP);
    let ramp = ["-f", "lavfi", "-i", "color=c=black:s=64x36:r=30:d=1", "-vf", "geq=lum=16+N*6:cb=128:cr=128"];
    ffmpeg(
        &tools,
        &[&ramp[..], &["-c:v", "libx264", "-qp", "0", "-pix_fmt", "yuv420p"]].concat(),
        &dir.path().join("ramp.mp4"),
    );
    let out = tempfile::tempdir().unwrap();
    let job =
        Job { width: 64, height: 36, range: Some(0.2..0.7), ..Job::new(dir.path(), out.path().join("ramp-out.mp4")) };
    let report = render(&job, &tools).unwrap();
    assert_eq!((report.frames, report.videos, report.audio_tracks), (15, 1, 0));
    let gray = out.path().join("gray.raw");
    let input = out.path().join("ramp-out.mp4");
    ffmpeg(&tools, &["-i", input.to_str().unwrap(), "-vf", "scale=1:1,format=gray", "-f", "rawvideo"], &gray);
    let seen: Vec<i32> = std::fs::read(&gray).unwrap().into_iter().map(i32::from).collect();
    let expected: Vec<i32> = (0..15).map(|frame| (f64::from((frame + 6) * 6) * 255.0 / 219.0).round() as i32).collect();
    let close = seen.len() == 15 && seen.iter().zip(&expected).all(|(seen, expected)| (seen - expected).abs() <= 2);
    assert!(close, "luma per frame {seen:?}, expected {expected:?}");
}
